namespace DyeHouseERP.Application.Checks.Commands;

/// <summary>
/// Registers an incoming customer check (spec section 37 "Incoming Customer Checks").
/// The check number is the bank's own number - it is not generated by this system,
/// but it is checked for duplicates within the same bank/customer so the same
/// instrument can never be registered twice.
/// </summary>
public record RegisterCustomerCheckCommand(
    string CheckNumber, string BankName, decimal Amount,
    DateTime IssueDate, DateTime DueDate, string Issuer, Guid CustomerId,
    string Currency = "EGP", string? BranchName = null, string? CustomerReference = null,
    string? Notes = null, bool ConfirmInHandNow = true, DateTime? ReceivedDate = null)
    : IRequest<CheckDto>;

public class RegisterCustomerCheckCommandValidator : AbstractValidator<RegisterCustomerCheckCommand>
{
    public RegisterCustomerCheckCommandValidator()
    {
        RuleFor(x => x.CheckNumber).NotEmpty().MaximumLength(50);
        RuleFor(x => x.BankName).NotEmpty().MaximumLength(200);
        RuleFor(x => x.Issuer).NotEmpty().MaximumLength(200);
        RuleFor(x => x.Amount).GreaterThan(0);
        RuleFor(x => x.CustomerId).NotEmpty();
    }
}

public class RegisterCustomerCheckCommandHandler : IRequestHandler<RegisterCustomerCheckCommand, CheckDto>
{
    private readonly IApplicationDbContext _db;
    private readonly ICurrentUserService _currentUser;
    public RegisterCustomerCheckCommandHandler(IApplicationDbContext db, ICurrentUserService currentUser)
    { _db = db; _currentUser = currentUser; }

    public async Task<CheckDto> Handle(RegisterCustomerCheckCommand request, CancellationToken cancellationToken)
    {
        var customer = await _db.Customers.AsNoTracking()
            .FirstOrDefaultAsync(c => c.Id == request.CustomerId, cancellationToken)
            ?? throw new NotFoundException("Customer", request.CustomerId);

        await CheckRules.EnsureNotDuplicateAsync(_db, request.BankName, request.CheckNumber, request.CustomerId, null, cancellationToken);

        var entity = new Check(
            request.CheckNumber, CheckDirection.CustomerCheck, request.BankName, request.Amount,
            request.IssueDate, request.DueDate, request.Issuer, customer.Name, CheckHolderType.Customer,
            _currentUser.UserName, request.BranchName, request.Currency, request.CustomerReference,
            request.Notes, customerId: customer.Id);

        if (request.ConfirmInHandNow)
        {
            var company = await CheckRules.ResolveCompanyHolderNameAsync(_db, cancellationToken);
            entity.ConfirmReceipt(request.ReceivedDate ?? request.IssueDate, company, _currentUser.UserName);
        }

        _db.Checks.Add(entity);
        await _db.SaveChangesAsync(cancellationToken);

        var list = await CheckDtoBuilder.BuildManyAsync(_db, new List<Check> { entity }, true, cancellationToken);
        return list[0];
    }
}

/// <summary>
/// Registers an outgoing supplier check (spec section 37 "Outgoing Supplier Checks").
/// Issued by the company, so the original holder is the company itself and the
/// bank account it is drawn on is recorded for the cash effect when it clears.
/// </summary>
public record RegisterSupplierCheckCommand(
    string CheckNumber, string BankName, decimal Amount,
    DateTime IssueDate, DateTime DueDate, string Issuer, Guid SupplierId,
    Guid? TreasuryAccountId = null, string Currency = "EGP", string? BranchName = null,
    string? Notes = null, bool HandOverNow = false, DateTime? HandOverDate = null, string? Reason = null)
    : IRequest<CheckDto>;

public class RegisterSupplierCheckCommandValidator : AbstractValidator<RegisterSupplierCheckCommand>
{
    public RegisterSupplierCheckCommandValidator()
    {
        RuleFor(x => x.CheckNumber).NotEmpty().MaximumLength(50);
        RuleFor(x => x.BankName).NotEmpty().MaximumLength(200);
        RuleFor(x => x.Issuer).NotEmpty().MaximumLength(200);
        RuleFor(x => x.Amount).GreaterThan(0);
        RuleFor(x => x.SupplierId).NotEmpty();
    }
}

public class RegisterSupplierCheckCommandHandler : IRequestHandler<RegisterSupplierCheckCommand, CheckDto>
{
    private readonly IApplicationDbContext _db;
    private readonly ICurrentUserService _currentUser;
    public RegisterSupplierCheckCommandHandler(IApplicationDbContext db, ICurrentUserService currentUser)
    { _db = db; _currentUser = currentUser; }

    public async Task<CheckDto> Handle(RegisterSupplierCheckCommand request, CancellationToken cancellationToken)
    {
        var supplier = await _db.Suppliers.AsNoTracking()
            .FirstOrDefaultAsync(s => s.Id == request.SupplierId, cancellationToken)
            ?? throw new NotFoundException("Supplier", request.SupplierId);

        await CheckRules.EnsureNotDuplicateAsync(_db, request.BankName, request.CheckNumber, null, request.SupplierId, cancellationToken);

        var company = await CheckRules.ResolveCompanyHolderNameAsync(_db, cancellationToken);

        var entity = new Check(
            request.CheckNumber, CheckDirection.SupplierCheck, request.BankName, request.Amount,
            request.IssueDate, request.DueDate, request.Issuer, company, CheckHolderType.Company,
            _currentUser.UserName, request.BranchName, request.Currency, customerReference: null,
            notes: request.Notes, customerId: null, supplierId: supplier.Id);

        if (request.TreasuryAccountId.HasValue)
        {
            var accountExists = await _db.TreasuryAccounts.AsNoTracking()
                .AnyAsync(a => a.Id == request.TreasuryAccountId.Value, cancellationToken);
            if (!accountExists) throw new NotFoundException("Treasury Account", request.TreasuryAccountId.Value);

            // The account an outgoing check is drawn on is recorded for the cash effect -
            // it is not a "deposit", and it never changes who holds the instrument.
            entity.SetDrawnOnAccount(request.TreasuryAccountId.Value);
        }

        if (request.HandOverNow)
        {
            entity.EndorseToSupplier(supplier.Id, supplier.Name, request.HandOverDate ?? request.IssueDate,
                _currentUser.UserName, request.Reason);
        }

        _db.Checks.Add(entity);
        await _db.SaveChangesAsync(cancellationToken);

        var list = await CheckDtoBuilder.BuildManyAsync(_db, new List<Check> { entity }, true, cancellationToken);
        return list[0];
    }
}

/// <summary>Confirms a customer check is physically in the company's hands (Received -&gt; In Hand).</summary>
public record ConfirmCheckReceiptCommand(Guid Id, DateTime? MovementDate = null) : IRequest<CheckDto>;

public class ConfirmCheckReceiptCommandHandler : IRequestHandler<ConfirmCheckReceiptCommand, CheckDto>
{
    private readonly IApplicationDbContext _db;
    private readonly ICurrentUserService _currentUser;
    public ConfirmCheckReceiptCommandHandler(IApplicationDbContext db, ICurrentUserService currentUser)
    { _db = db; _currentUser = currentUser; }

    public async Task<CheckDto> Handle(ConfirmCheckReceiptCommand request, CancellationToken cancellationToken)
    {
        var company = await CheckRules.ResolveCompanyHolderNameAsync(_db, cancellationToken);
        return await CheckWorkflow.MutateAsync(_db, request.Id,
            entity => entity.ConfirmReceipt(request.MovementDate ?? DateTime.UtcNow, company, _currentUser.UserName),
            cancellationToken);
    }
}

/// <summary>
/// Endorses/transfers the SAME instrument to a supplier (spec section 39: Customer -&gt; Company -&gt; Supplier).
/// No new check row, no new cash: the holder changes and a movement is appended.
/// </summary>
public record EndorseCheckToSupplierCommand(
    Guid Id, Guid SupplierId, DateTime MovementDate, string? Reason = null, DateTime? DueDate = null)
    : IRequest<CheckDto>;

public class EndorseCheckToSupplierCommandValidator : AbstractValidator<EndorseCheckToSupplierCommand>
{
    public EndorseCheckToSupplierCommandValidator()
    {
        RuleFor(x => x.Id).NotEmpty();
        RuleFor(x => x.SupplierId).NotEmpty();
    }
}

public class EndorseCheckToSupplierCommandHandler : IRequestHandler<EndorseCheckToSupplierCommand, CheckDto>
{
    private readonly IApplicationDbContext _db;
    private readonly ICurrentUserService _currentUser;
    public EndorseCheckToSupplierCommandHandler(IApplicationDbContext db, ICurrentUserService currentUser)
    { _db = db; _currentUser = currentUser; }

    public async Task<CheckDto> Handle(EndorseCheckToSupplierCommand request, CancellationToken cancellationToken)
    {
        var supplier = await _db.Suppliers.AsNoTracking()
            .FirstOrDefaultAsync(s => s.Id == request.SupplierId, cancellationToken)
            ?? throw new NotFoundException("Supplier", request.SupplierId);

        return await CheckWorkflow.MutateAsync(_db, request.Id,
            entity => entity.EndorseToSupplier(supplier.Id, supplier.Name, request.MovementDate,
                _currentUser.UserName, request.Reason),
            cancellationToken);
    }
}

/// <summary>Deposits a check into a bank account. The cash effect is posted when the check actually clears (see ClearCheckCommand).</summary>
public record DepositCheckCommand(Guid Id, Guid TreasuryAccountId, DateTime? MovementDate = null, string? Notes = null)
    : IRequest<CheckDto>;

public class DepositCheckCommandHandler : IRequestHandler<DepositCheckCommand, CheckDto>
{
    private readonly IApplicationDbContext _db;
    private readonly ICurrentUserService _currentUser;
    public DepositCheckCommandHandler(IApplicationDbContext db, ICurrentUserService currentUser)
    { _db = db; _currentUser = currentUser; }

    public async Task<CheckDto> Handle(DepositCheckCommand request, CancellationToken cancellationToken)
    {
        var account = await _db.TreasuryAccounts.AsNoTracking()
            .FirstOrDefaultAsync(a => a.Id == request.TreasuryAccountId, cancellationToken)
            ?? throw new NotFoundException("Treasury Account", request.TreasuryAccountId);

        return await CheckWorkflow.MutateAsync(_db, request.Id,
            entity => entity.Deposit(account.Id, account.Name, request.MovementDate ?? DateTime.UtcNow,
                _currentUser.UserName, request.Notes),
            cancellationToken);
    }
}

/// <summary>
/// Marks a deposited check as cleared and posts the real cash/bank movement to the treasury
/// ledger (spec section 40: checks integrate with treasury, banks and accounting).
/// A cleared customer check increases the bank account; a cleared outgoing supplier check
/// decreases it. Nothing is ever posted twice: only this transition posts money.
/// </summary>
public record ClearCheckCommand(Guid Id, DateTime? MovementDate = null, string? Notes = null, Guid? TreasuryAccountId = null)
    : IRequest<CheckDto>;

public class ClearCheckCommandHandler : IRequestHandler<ClearCheckCommand, CheckDto>
{
    private readonly IApplicationDbContext _db;
    private readonly ICurrentUserService _currentUser;
    private readonly IPeriodCloseService _periodClose;

    public ClearCheckCommandHandler(IApplicationDbContext db, ICurrentUserService currentUser, IPeriodCloseService periodClose)
    { _db = db; _currentUser = currentUser; _periodClose = periodClose; }

    public async Task<CheckDto> Handle(ClearCheckCommand request, CancellationToken cancellationToken)
    {
        var entity = await _db.Checks.Include(c => c.Movements)
            .FirstOrDefaultAsync(c => c.Id == request.Id, cancellationToken)
            ?? throw new NotFoundException("Check", request.Id);

        var movementDate = request.MovementDate ?? DateTime.UtcNow;
        await _periodClose.EnsureOpenAsync(movementDate, cancellationToken);

        var accountId = request.TreasuryAccountId ?? entity.TreasuryAccountId
            ?? throw new DomainException("The check must be deposited into a bank/treasury account before it can be cleared.");

        var account = await _db.TreasuryAccounts.AsNoTracking()
            .FirstOrDefaultAsync(a => a.Id == accountId, cancellationToken)
            ?? throw new NotFoundException("Treasury Account", accountId);

        if (entity.TreasuryAccountId != account.Id)
        {
            if (entity.Status is CheckStatus.Received or CheckStatus.InHand)
                entity.Deposit(account.Id, account.Name, movementDate, _currentUser.UserName);
            else
                entity.SetDrawnOnAccount(account.Id);
        }

        entity.Clear(movementDate, _currentUser.UserName, request.Notes);

        var direction = entity.Direction == CheckDirection.CustomerCheck ? TreasuryDirection.In : TreasuryDirection.Out;
        var description = entity.Direction == CheckDirection.CustomerCheck
            ? $"Cleared customer check {entity.CheckNumber} ({entity.BankName})"
            : $"Cleared supplier check {entity.CheckNumber} ({entity.BankName})";

        _db.TreasuryTransactions.Add(new TreasuryTransaction(
            account.Id, movementDate, DocumentType.CheckRegister, entity.CheckNumber, entity.Id,
            entity.Amount, direction, description, _currentUser.UserName));

        await _db.SaveChangesAsync(cancellationToken);

        var list = await CheckDtoBuilder.BuildManyAsync(_db, new List<Check> { entity }, true, cancellationToken);
        return list[0];
    }
}

