internal static class CheckWorkflow
{
    public static async Task<CheckDto> MutateAsync(
        IApplicationDbContext db, Guid id, Action<Check> mutate, CancellationToken cancellationToken)
    {
        var entity = await db.Checks.Include(c => c.Movements)
            .FirstOrDefaultAsync(c => c.Id == id, cancellationToken)
            ?? throw new NotFoundException("Check", id);

        mutate(entity);
        await db.SaveChangesAsync(cancellationToken);

        var list = await CheckDtoBuilder.BuildManyAsync(db, new List<Check> { entity }, true, cancellationToken);
        return list[0];
    }
}

internal static class CheckRules
{
    /// <summary>
    /// Duplicate instrument detection (spec section 55): the same bank + number can only exist once for the
    /// same customer or supplier, so the identical physical check can never enter the register twice.
    /// </summary>
    public static async Task EnsureNotDuplicateAsync(
        IApplicationDbContext db, string bankName, string checkNumber, Guid? customerId, Guid? supplierId,
        CancellationToken cancellationToken)
    {
        var bank = bankName.Trim();
        var number = checkNumber.Trim();

        var duplicate = await db.Checks.AsNoTracking().AnyAsync(c =>
            c.BankName == bank && c.CheckNumber == number && c.CustomerId == customerId && c.SupplierId == supplierId,
            cancellationToken);

        if (duplicate)
            throw new DomainException(
                $"Check number '{number}' from '{bank}' is already registered for this party. " +
                "The same physical instrument must never be registered twice.");
    }

    /// <summary>The company's own display name, used as the holder when it holds the instrument. Falls back to a neutral label.</summary>
    public static async Task<string> ResolveCompanyHolderNameAsync(IApplicationDbContext db, CancellationToken cancellationToken)
    {
        var settings = await db.CompanySettings.AsNoTracking().FirstOrDefaultAsync(cancellationToken);
        if (settings is null) return "Company";
        return string.IsNullOrWhiteSpace(settings.CompanyNameEn) ? settings.CompanyNameAr : settings.CompanyNameEn;
    }
}
